S.append(S2(c,B+' · 2','Các cách định dạng khác (để đọc hiểu)',CODE('x, n = 3.14159, 7\nprint("%.2f" % x)\nprint("%d + %d" % (n, n))\nprint("{:.2f} - {}".format(x, n))\nprint("{0} {1} {0}".format("a", "b"))\nprint(round(x, 2))',20)+R('x, n = 3.14159, 7\nprint("%.2f" % x)\nprint("%d + %d" % (n, n))\nprint("{:.2f} - {}".format(x, n))\nprint("{0} {1} {0}".format("a", "b"))\nprint(round(x, 2))','',22),card('Ba cách, cùng một việc',ul(['<b>%</b>: kiểu cũ (từ ngôn ngữ C): <code>%d</code> nguyên, <code>%f</code> thực, <code>%s</code> xâu.','<b>.format()</b>: kiểu trung gian.','<b>f-string</b>: <b>nên dùng</b> (ngắn, dễ đọc).','<code>round(x, 2)</code> trả về <b>số</b> (có thể bỏ số 0 cuối: 2.5), còn định dạng cho ra <b>xâu</b>.'],7))))
