S.append(S2(c,B+' · 3','Bài mẫu 1: chu vi và diện tích hình tròn',card('Phân tích',P('<b>Đề:</b> nhập bán kính r, in chu vi và diện tích (π = 3.14159), làm tròn 2 chữ số thập phân.','<b>Vào:</b> r (số thực). <b>Ra:</b> hai số.','<b>Công thức:</b> C = 2πr ; S = πr².','<b>Tính tay</b> với r = 2: C = 12.566… → 12.57; S = 12.566… → 12.57.')),CODE('PI = 3.14159\nr = float(input())\nc = 2 * PI * r\ns = PI * r ** 2\nprint(f"{c:.2f} {s:.2f}")',22)+R('PI = 3.14159\nr = float(input())\nc = 2 * PI * r\ns = PI * r ** 2\nprint(f"{c:.2f} {s:.2f}")','2\n',26,'Chạy thử (r = 2)')+KEY('Khớp tính tay (12.57 12.57). Dùng <code>r ** 2</code> chứ không phải <code>r * 2</code>.')))
S.append(S2(c,B+' · 3','Bài mẫu 2: điểm trung bình có hệ số',card('Phân tích',P('<b>Đề:</b> Toán hệ số 2, Văn hệ số 2, Anh hệ số 1. Nhập ba điểm, in điểm trung bình (1 chữ số thập phân).','<b>Công thức:</b> TB = (2·Toán + 2·Văn + Anh) / 5.','<b>Tính tay</b> (8, 7, 9): (16 + 14 + 9)/5 = 39/5 = <b>7.8</b>.')),CODE('toan = float(input())\nvan = float(input())\nanh = float(input())\ntb = (2 * toan + 2 * van + anh) / 5\nprint(f"{tb:.1f}")',22)+R('toan = float(input())\nvan = float(input())\nanh = float(input())\ntb = (2 * toan + 2 * van + anh) / 5\nprint(f"{tb:.1f}")','8\n7\n9\n',26,'Chạy thử (8, 7, 9)')+WARN('Thiếu ngoặc: <code>2*toan + 2*van + anh / 5</code> chỉ chia <b>anh</b> cho 5. Ngoặc quyết định thứ tự tính.')))
S.append(S2(c,B+' · 3','Bài mẫu 3: đổi giây ra giờ – phút – giây',card('Phân tích',P('<b>Đề:</b> nhập số giây s (0 ≤ s ≤ 86399), in dạng hh:mm:ss.','<b>Cách làm:</b> giờ = s // 3600; phút = s % 3600 // 60; giây = s % 60.','<b>Tính tay</b> s = 3725: 3725 // 3600 = 1; 125 // 60 = 2; 3725 % 60 = 5 → 01:02:05.')),CODE('s = int(input())\ngio = s // 3600\nphut = s % 3600 // 60\ngiay = s % 60\nprint(f"{gio:02d}:{phut:02d}:{giay:02d}")',22)+R('s = int(input())\ngio = s // 3600\nphut = s % 3600 // 60\ngiay = s % 60\nprint(f"{gio:02d}:{phut:02d}:{giay:02d}")','3725\n',26,'Chạy thử (3725)')+KEY('<code>:02d</code> đệm số 0 để luôn đủ 2 chữ số: 1 → <b>01</b>.')))
S.append(S2(c,B+' · 3','Bài mẫu 4: tổng các chữ số và số đảo (3 chữ số)',card('Phân tích',P('<b>Đề:</b> nhập số nguyên dương có đúng 3 chữ số. In tổng các chữ số và số đảo.','<b>Cách làm:</b> trăm = n // 100; chục = n // 10 % 10; đơn vị = n % 10.','<b>Tính tay</b> n = 482: 4 + 8 + 2 = <b>14</b>; đảo = 2·100 + 8·10 + 4 = <b>284</b>.')),CODE('n = int(input())\na, b, c = n // 100, n // 10 % 10, n % 10\nprint(a + b + c)\nprint(c * 100 + b * 10 + a)',22)+R('n = int(input())\na, b, c = n // 100, n // 10 % 10, n % 10\nprint(a + b + c)\nprint(c * 100 + b * 10 + a)','482\n',26,'Chạy thử (482)')+WARN('Nếu n = 120 thì số đảo là <b>021 = 21</b>: kết quả là số nên <b>mất số 0 đầu</b>.')))
S.append(S2(c,B+' · 3','Bài mẫu 5: đổi tiền và chia nguyên',card('Phân tích',P('<b>Đề:</b> rút số tiền n (nghìn đồng, bội của 10). In số tờ 500 nghìn, 100 nghìn, 50 nghìn, 10 nghìn ít tờ nhất.','<b>Cách làm:</b> lấy tờ lớn trước: <b>//</b> cho số tờ, <b>%</b> cho số tiền còn lại.','<b>Tính tay</b> n = 1680: 1680 // 500 = 3 (dư 180); 180 // 100 = 1 (dư 80); 80 // 50 = 1 (dư 30); 30 // 10 = 3.')),CODE('n = int(input())\nt500, n = n // 500, n % 500\nt100, n = n // 100, n % 100\nt50, n = n // 50, n % 50\nt10 = n // 10\nprint(t500, t100, t50, t10)',21)+R('n = int(input())\nt500, n = n // 500, n % 500\nt100, n = n // 100, n % 100\nt50, n = n // 50, n % 50\nt10 = n // 10\nprint(t500, t100, t50, t10)','1680\n',26,'Chạy thử (1680)')+KEY('Mẫu hình <b>“lấy thương, giữ dư”</b> dùng lại cho đổi giờ, đổi đơn vị, đổi tiền.')))
S.append(S2(c,B+' · 3','Bài mẫu 6: BMI và so sánh logic',card('Phân tích',P('<b>Đề:</b> nhập cân nặng (kg) và chiều cao (m). Tính BMI = cân nặng / chiều cao². In BMI (1 chữ số thập phân) và <b>True/False</b> nếu thuộc khoảng bình thường 18.5 ≤ BMI &lt; 25.','<b>Tính tay</b> (60, 1.7): 1.7² = 2.89; 60 / 2.89 = 20.76… → <b>20.8</b>, bình thường: True.')),CODE('kg = float(input())\nm = float(input())\nbmi = kg / m ** 2\nprint(f"{bmi:.1f}")\nprint(18.5 <= bmi < 25)',22)+R('kg = float(input())\nm = float(input())\nbmi = kg / m ** 2\nprint(f"{bmi:.1f}")\nprint(18.5 <= bmi < 25)','60\n1.7\n',26,'Chạy thử (60 và 1.7)')+KEY('Kết hợp <b>tính toán</b> với <b>so sánh dây</b> cho giá trị bool: đây chính là cách dùng điều kiện sẽ học ở bài rẽ nhánh.')))
